head.script:
// 화면 리사이징

scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gIsurCd;
scwin.gDtecDd;
scwin.gSeq;
scwin.gChgStatCd;
scwin.regMode; // 'REG', 'MOD'
scwin.gComAbbrv;
scwin.gChgTpNm;
scwin.gStrtDd;
scwin.gChgRsnNm;
scwin.gMisc;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.libRoundPanel.PanelToGroupBox(panel_1);
        await scwin.setCode();

        // 회사정보 로딩
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30650.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30650.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_List.errorMsg) {
            await $c.win.alert(dts_List.errorMsg);
        } else {
            $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30650.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30650.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        gSEQ = dts_List.getCellData(Number(row), "SEQ");
        gDESIGN_ADVSER_ISUR_CD = dts_List.getCellData(Number(row), "DESIGN_ADVSER_ISUR_CD");
        gDESIGN_ADVSER_COM_ABBRV = dts_List.getCellData(Number(row), "DESIGN_ADVSER_COM_ABBRV");
        gADVCE_COM_ISUR_CD = dts_List.getCellData(Number(row), "ADVCE_COM_ISUR_CD");
        gADVCE_COM_ABBRV = dts_List.getCellData(Number(row), "ADVCE_COM_ABBRV");
        gADVCE_COM_APPL_TP_NM = dts_List.getCellData(Number(row), "ADVCE_COM_APPL_TP_NM");
        gADVCE_COM_APPL_TP_CD = dts_List.getCellData(Number(row), "ADVCE_COM_APPL_TP_CD");
        gSTRT_DD = dts_List.getCellData(Number(row), "STRT_DD");
        gAPPL_REQ_DD = dts_List.getCellData(Number(row), "APPL_REQ_DD");
        gAPPL_DDTM = dts_List.getCellData(Number(row), "APPL_DDTM");
        gADVCE_COM_PROCS_STAT_NM = dts_List.getCellData(Number(row), "ADVCE_COM_PROCS_STAT_NM");
        gADVCE_COM_PROCS_STAT_CD = dts_List.getCellData(Number(row), "ADVCE_COM_PROCS_STAT_CD");
        gCONTRT_DD = dts_List.getCellData(Number(row), "CONTRT_DD");
        gRELEAS_DD = dts_List.getCellData(Number(row), "RELEAS_DD");
        gREVWR_NM = dts_List.getCellData(Number(row), "REVWR_NM");
        gREVW_DDTM = dts_List.getCellData(Number(row), "REVW_DDTM");
        gAPPROVR_NM = dts_List.getCellData(Number(row), "APPROVR_NM");
        gAPPROV_DDTM = dts_List.getCellData(Number(row), "APPROV_DDTM");
        gEMP_NM = dts_List.getCellData(Number(row), "EMP_NM");
        gDEP_NM = dts_List.getCellData(Number(row), "DEP_NM");
        if (colid === "ADVCE_COM_PROCS_STAT_NM") {
            // 승인상태 클릭 시
            let url = "/issueinfo/ULDSTF30651.gfm";
            const winTitle = "지정자문인 자문기업 지정(해제)";
            await $c.frame.CreateDialogFrame("ULDSTF30651", url, winTitle, 100, 100, 730, 350, "window");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30650.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name cmb_DEP_CD_onselchange
 * @description cmb_DEP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DEP_CD_onselchange = function() {
    try {
        scwin.gDepCd = cmb_DEP_CD.getValue(); // ;.ValueOfIndex("VALUE", cmb_DEP_CD.Index);

        dts_EMP_NO.UseFilter = true;
        dts_EMP_NO.Filter();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30650.cmb_DEP_CD_onselchange" });
    }
};

/**
 * @method
 * @name dts_EMP_NO_OnFilter
 * @description EMP NO On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_OnFilter = function(row) {
    try {
        if (scwin.gDepCd === "") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_EMP_NO.getCellData(row, "dep_cd") === scwin.gDepCd ||
                dts_EMP_NO.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30650.dts_EMP_NO_OnFilter" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30650.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30650.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30650.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30650.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30650.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30650.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30650.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30650.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30650.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30650.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30650.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF30650.xml', SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "지정자문인 담당법인 변경처리 현황", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30650.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name img_FromCal_onclick
 * @description img_FromCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_FromCal_onclick = function() {
    try {
        popUpCalendar2(edt_FromDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30650.img_FromCal_onclick" });
    }
};

/**
 * @method
 * @name img_ToCal_onclick
 * @description img_ToCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ToCal_onclick = function() {
    try {
        popUpCalendar2(edt_ToDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30650.img_ToCal_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_FromDate, edt_ToDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30650.cmb_PeriodTp_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description 페이지 로딩 시 필요한 변수 초기화
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_EMP_NO",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_EMP_NO=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_DEP_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_DEP_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 조회일자 오늘로 셋팅
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    // edt_FromDate.text = vCurDate;     // 현재날짜
    // edt_ToDate.text =vCurDate;    // 현재날짜

    // 부서코드 로그인 사용자 부서로 셋팅
    cmb_DEP_CD.setValue(js_dep_cd);
    if (cmb_DEP_CD.getValue() === '') {
        cmb_DEP_CD.setSelectedIndex(0);
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const vISUR_CD = txb_isur_cd.getValue();
    const vSTRT_DT = edt_FromDate.getValue();
    const vEND_DT = edt_ToDate.getValue();
    const vDEP_CD = cmb_DEP_CD.getValue();
    const vEMP_NO = cmb_EMP_NO.getValue();
    const vADVCE_COM_PROCS_STAT_CD = cmb_stat_cd.getValue();
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&ADVCE_COM_PROCS_STAT_CD=" + $c.stf.trim(vADVCE_COM_PROCS_STAT_CD);
    url += "&STRT_DT=" + vSTRT_DT;
    url += "&END_DT=" + vEND_DT;
    url += "&DEP_CD=" + vDEP_CD;
    url += "&EMP_NO=" + vEMP_NO;
    url += "&SCREN_ID=" + 'ULDSTF30650.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
